ALTER POLICY pc_imp_planta ON public.pesajes_cintas USING (EXISTS(SELECT 1 FROM public.pesajes_cintas_lotes l WHERE l.id=lote_id AND (l.imp_bobina_id IS NULL OR public.user_sees_planta(auth.uid(),l.planta_corte_id)))); DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pc_puede_editar_corte(uuid)'::regprocedure) INTO d; d:=replace(d,'IF v_ref IS NULL THEN','IF EXISTS(SELECT 1 FROM public.pesajes_cintas_lotes l WHERE l.id=_lote_id AND l.imp_bobina_id IS NOT NULL AND NOT public.user_sees_planta(v_uid,l.planta_corte_id)) THEN RETURN jsonb_build_object(''puede'',false,''motivo'',''Sin permiso de planta.''); END IF; IF v_ref IS NULL THEN'); EXECUTE d; END $$;